import sys
import requests
from concurrent.futures import ThreadPoolExecutor
from time import sleep

def process_url(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code
    except:
        return 0

def main():
    if len(sys.argv) != 4:
        print("Usage: python report.py <input_path> <output_path> <N>")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]
    N = int(sys.argv[3])

    with open(input_path, 'r') as file:
        urls = [line.strip() for line in file if line.strip()]

    status_codes = []
    for i in range(0, len(urls), N):
        group = urls[i:i+N]
        with ThreadPoolExecutor(max_workers=1) as executor:
            futures = [executor.submit(process_url, url) for url in group]
            for future in futures:
                status_codes.append(future.result())
        sleep(1)

    html_content = """<!DOCTYPE html>
<html>
<head>
    <title>URL Status Report</title>
    <style>
        table {
            border-collapse: collapse;
            width: 100%;
        }
        th, td {
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }
        th {
            background-color: #f2f2f2;
        }
    </style>
</head>
<body>
    <table>
        <tr>
            <th>URL</th>
            <th>Status Code</th>
        </tr>
"""
    for url, status in zip(urls, status_codes):
        html_content += f"""        <tr>
            <td>{url}</td>
            <td>{status}</td>
        </tr>
"""
    html_content += """    </table>
</body>
</html>"""

    with open(output_path, 'w') as file:
        file.write(html_content)

if __name__ == "__main__":
    main()
